// createIssuesListIssuesHandler creates a handler for GET /api/teams/{teamId}/issues
//
// A team's issues, newest first unless the caller sorts them, searched
// by their text and filtered by their fields.
//
// It serves the list of Issue, a table of fixture-tracker-db, from its
// repository in one transaction (D106): no implementation method serves
// it.
func createIssuesListIssuesHandler(db orm.DatabaseInterface) gohttp.HandlerFunc {
	// A filter's values (D106): each field's value as an item of a query
	// list of its type, its error recorded at filter[field].
	filterStatusArg := bodyargs.NewArg("filter[status]", bodyargs.String)
	filterPriorityArg := bodyargs.NewArg("filter[priority]", bodyargs.Integer, bodyargs.Min(-9007199254740991), bodyargs.Max(9007199254740991))
	filterTitleArg := bodyargs.NewArg("filter[title]", bodyargs.String)
	filterEstimateArg := bodyargs.NewArg("filter[estimate]", bodyargs.Number)
	filterDueOnArg := bodyargs.NewArg("filter[dueOn]", bodyargs.String, bodyargs.MaxLength(40))
	filterAssigneeIdArg := bodyargs.NewArg("filter[assigneeId]", bodyargs.String, bodyargs.Pattern(`^([0-9A-Za-z]{1,22}|[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})$`))
	filterCreatedAtArg := bodyargs.NewArg("filter[createdAt]", bodyargs.String)
	return func(w gohttp.ResponseWriter, r *gohttp.Request) {
		// Extract path parameters, each percent-decoded once
		TeamIdStr, err := runtimerouting.PathParam(r, "teamId")
		if err != nil {
			RespondError(w, r, gohttp.StatusBadRequest, "teamId must be percent-encoded UTF-8")
			return
		}
		if TeamIdStr == "" {
			RespondError(w, r, gohttp.StatusBadRequest, "teamId is required")
			return
		}
		TeamId, err := types.ParseIdentityUUID(TeamIdStr)
		if err != nil {
			RespondError(w, r, gohttp.StatusBadRequest, "teamId must be a valid UUID")
			return
		}
		// Extract query parameters
		Q := parseStringQueryParamPtr(r, "q")
		if Q != nil && len([]rune(*Q)) > 100 {
			validationErrors := types.NewValidationErrors()
			validationErrors.SetFieldErrors("q", []types.ValidationError{{Validator: "maxLength", Message: "must be at most 100 characters"}})
			RespondValidationErrors(w, r, validationErrors)
			return
		}
		// Read the request's filters (FilterBy, D106): the bracket form,
		// filter[field]=value and filter[field][op]=value, its own reader,
		// whose refusal is the 400 every server answers at filter[field].
		// Each value is then decoded as an item of a query list of its
		// field's type.
		filterRequest, ok := filterparse.Read(w, r, filterparse.Spec{Fields: []filterparse.FieldSpec{{Name: "status", Operators: []filterparse.Operator{"eq", "in"}}, {Name: "priority", Operators: []filterparse.Operator{"eq", "in", "gt", "gte", "lt", "lte"}}, {Name: "title", Operators: []filterparse.Operator{"eq", "in", "contains"}}, {Name: "estimate", Operators: []filterparse.Operator{"eq", "in", "gt", "gte", "lt", "lte", "isNull"}}, {Name: "dueOn", Operators: []filterparse.Operator{"eq", "in", "gt", "gte", "lt", "lte", "isNull"}}, {Name: "assigneeId", Operators: []filterparse.Operator{"eq", "in", "isNull"}}, {Name: "createdAt", Operators: []filterparse.Operator{"eq", "in", "gt", "gte", "lt", "lte"}}}})
		if !ok {
			return
		}
		filterErrors := types.NewValidationErrors()
		filters := IssuesListIssuesFilter{
			Status:     filterparse.DecodeEquals[types.IssueStatus](filterErrors, filterRequest, "status", filterStatusArg),
			Priority:   filterparse.DecodeOrdered[int64](filterErrors, filterRequest, "priority", filterPriorityArg),
			Title:      filterparse.DecodeText[string](filterErrors, filterRequest, "title", filterTitleArg),
			Estimate:   filterparse.DecodeOrdered[float64](filterErrors, filterRequest, "estimate", filterEstimateArg),
			DueOn:      filterparse.DecodeOrdered[types.TemporalDate](filterErrors, filterRequest, "dueOn", filterDueOnArg),
			AssigneeId: filterparse.DecodeEquals[types.IdentityUUID](filterErrors, filterRequest, "assigneeId", filterAssigneeIdArg),
			CreatedAt:  filterparse.DecodeOrdered[types.TemporalDateTime](filterErrors, filterRequest, "createdAt", filterCreatedAtArg),
		}
		if filterErrors.HasErrors() {
			RespondValidationErrors(w, r, filterErrors)
			return
		}

		// Read the page's cursor and limit (@paginated): its own reader, whose
		// refusal is the 400 every server answers at cursor or limit.
		// It also reads sort, the page's sort (D60, amended), after the limit,
		// and unbinds the cursor from the sort it was returned under, so the
		// implementation reads its own key.
		page, ok := paging.Read(w, r, paging.Spec{DefaultLimit: 2, MaxLimit: 5, Sort: &paging.SortSpec{Param: "sort", Fields: []string{"createdAt", "priority", "title"}, Default: paging.Sort{Field: "createdAt", Desc: true}}})
		if !ok {
			return
		}

		// Ensure request context is still valid before entering implementation logic.
		if err := CheckContext(r.Context()); err != nil {
			logger := LoggerFromContext(r.Context())
			RespondAppError(w, logger, err)
			return
		}

		// Serve the operation from its table, as the request's caller (D106)
		result, err := tableIssuesListIssues(r.Context(), db, TeamId, Q, filters, page)
		if err != nil {
			respondTableError(w, r, err)
			return
		}
		// The next page's cursor names the sort the page was read in (D60,
		// amended); a next no router reads back under it is the
		// implementation's error.
		if result, err = paging.Bind(result, page); err != nil {
			RespondAppError(w, LoggerFromContext(r.Context()), err)
			return
		}

		// Respond with result
		// The page is the envelope's data, {items, next}: nil items are [] and
		// no next is null.
		RespondJSONEnvelope(w, gohttp.StatusOK, result, r)
	}
}

